const float fc3_bias[NUM_ACTIONS] = {0.0f,0.15f,0.05f,0.08f,0.08f,0.05f,0.05f,0.02f,0.02f,0.12f,-0.20f};

/* ---- DQN Inference ---- */
static float _relu(float x) {
    return x > 0.0f ? x : 0.0f;
}

void dqn_inference(const float* input, float* output) {
    float hidden1[HIDDEN1_DIM];

    /* Layer 1: 16->128 FC + ReLU */
    for (int j = 0; j < HIDDEN1_DIM; j++) {
        float sum = fc1_bias[j];
        for (int i = 0; i < OBS_DIM; i++) {
            sum += input[i] * fc1_weight[i][j];
        }
        hidden1[j] = _relu(sum);
    }

    /* Layer 2: 128->64 FC + ReLU */
    float hidden2[HIDDEN2_DIM];
    for (int j = 0; j < HIDDEN2_DIM; j++) {
        float sum = fc2_bias[j];
        for (int i = 0; i < HIDDEN1_DIM; i++) {
            sum += hidden1[i] * fc2_weight[i][j];
        }
        hidden2[j] = _relu(sum);
    }

    /* Layer 3: 64->11 (no activation) */
    for (int j = 0; j < NUM_ACTIONS; j++) {
        float sum = fc3_bias[j];
        for (int i = 0; i < HIDDEN2_DIM; i++) {
            sum += hidden2[i] * fc3_weight[i][j];
        }
        output[j] = sum;
    }
}